<script setup lang="ts">
import PrivacyRequests from '../components/PrivacyRequests.vue';
import {ref} from 'vue';import Button from 'primevue/button';import InputText from 'primevue/inputtext';import {useToast} from 'primevue/usetoast';import {api,currentUser} from '../lib/api';import {useQuery} from '../composables/useQuery';import {roleNames,type Data} from '../lib/types';import QueryState from '../components/QueryState.vue';import StatusBadge from '../components/StatusBadge.vue';
const {data,loading,error,refresh}=useQuery(async()=>{const [system,me,config]=await Promise.all([(['OperationsAdmin','SecurityAdmin'].includes(currentUser.value?.role??'')?api('/admin/system'):Promise.resolve(null)),api('/me'),api('/app-config')]);return {system,me,config};});const name=ref(''),email=ref(''),editing=ref(false),busy=ref(false),toast=useToast();
async function save(){if(!data.value)return;busy.value=true;try{await api('/me/profile',{method:'PATCH',body:{expectedVersion:data.value.me.version,name:name.value,email:email.value||null}});if(currentUser.value)currentUser.value.name=name.value;editing.value=false;await refresh();toast.add({severity:'success',summary:'Đã lưu hồ sơ',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message});}finally{busy.value=false;}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">THIẾT LẬP KHÔNG GIAN</div><h1>Cấu hình hệ thống<span class="green-text">.</span></h1><p>Hồ sơ làm việc, trạng thái hạ tầng và các tính năng đã bật.</p></div></div><QueryState :loading="loading" :error="error" @retry="refresh"/><template v-if="data"><div class="settings-grid"><section class="panel"><div class="panel-header"><div><h2>Hồ sơ nhân sự</h2><p>Thông tin gắn với phiên làm việc hiện tại</p></div><Button v-if="!editing" label="Chỉnh sửa" text icon="pi pi-pencil" @click="name=data.me.name;email=data.me.email??'';editing=true"/></div><div class="settings-body"><template v-if="!editing"><div class="detail-grid"><div><span>Họ tên</span><strong>{{data.me.name}}</strong></div><div><span>Vai trò</span><strong>{{roleNames[data.me.role]}}</strong></div><div><span>Điện thoại</span><strong>{{data.me.phone}}</strong></div><div><span>Email</span><strong>{{data.me.email||'Chưa cập nhật'}}</strong></div></div></template><template v-else><label>Họ tên<InputText v-model="name" class="full-width"/></label><label>Email<InputText v-model="email" type="email" class="full-width"/></label><div class="heading-actions"><Button label="Hủy" text severity="secondary" @click="editing=false"/><Button label="Lưu hồ sơ" :loading="busy" :disabled="!name.trim()" @click="save"/></div></template></div></section><section v-if="data.system" class="panel"><div class="panel-header"><div><h2>Hạ tầng & xử lý nền</h2><p>Trạng thái từ máy chủ</p></div><span class="metric-icon green"><i class="pi pi-server"></i></span></div><div class="settings-body"><div class="key-row"><span>Cơ sở dữ liệu</span><b>{{data.system.database?.includes('Sqlite')?'SQLite · Local':'PostgreSQL'}}</b></div><div class="key-row"><span>Outbox đang chờ</span><b>{{data.system.pendingOutbox}}</b></div><div class="key-row"><span>Dead-letter cần xử lý</span><b>{{data.system.deadLetters}}</b></div><div class="key-row"><span>Múi giờ nghiệp vụ</span><b>{{data.config.timezone}}</b></div><div class="key-row"><span>Tiền tệ</span><b>{{data.config.currency}}</b></div></div></section></div><section class="panel"><div class="panel-header"><div><h2>Khả năng hệ thống</h2><p>Chỉ hiển thị tính năng khả dụng theo cấu hình backend</p></div></div><div class="capabilities-grid"><div v-for="item in [{key:'cash',name:'Tiền mặt',icon:'pi-wallet',description:'Nghĩa vụ thanh toán, thực thu và sổ cái'},{key:'onlinePayments',name:'Thanh toán trực tuyến',icon:'pi-credit-card',description:'P1 · Cần tích hợp gateway và đối soát'},{key:'promotions',name:'Khuyến mại',icon:'pi-ticket',description:'P1 · Ngân sách, tài trợ và lượt sử dụng'},{key:'payouts',name:'Rút tiền tự phục vụ',icon:'pi-arrow-up-right',description:'P1 · Hold số dư, phê duyệt và ngân hàng'},{key:'privateDocumentUpload',name:'Giấy tờ private',icon:'pi-file-check',description:'Upload local private · Cần adapter production'},{key:'push',name:'Thông báo đẩy',icon:'pi-bell',description:'Cần FCM/APNs và cấu hình thiết bị'}]" :key="item.key" class="capability"><span class="metric-icon" :class="data.config.featureFlags[item.key]?'green':'neutral'"><i class="pi" :class="item.icon"></i></span><div><strong>{{item.name}}</strong><p>{{item.description}}</p></div><StatusBadge :status="data.config.featureFlags[item.key]?'ACTIVE':'DRAFT'" :label="data.config.featureFlags[item.key]?'Đã bật':'Chưa bật'"/></div></div></section><PrivacyRequests v-if="currentUser?.role==='SecurityAdmin'"/></template></template>
